import path from "node:path";

export const generatedComment =
  "// Generated by scripts/generate-deployable-routes.mjs. Do not edit by hand.\n";
export const generatedFileMarker = `${generatedComment}\n`;

export const deployableRouteConfig = {
  "catalog-admin": {
    routesFileParts: ["deployables", "catalog-admin", "app", "context-routes.generated.ts"],
    routesDirParts: ["deployables", "catalog-admin", "app", "routes"],
    hostRoutes: new Set([
      "account-select.tsx",
      "index.tsx",
      "layout.tsx",
      "sign-in.tsx",
      "sign-out.tsx",
    ]),
  },
  "identity-admin": {
    routesFileParts: ["deployables", "identity-admin", "app", "context-routes.generated.ts"],
    routesDirParts: ["deployables", "identity-admin", "app", "routes"],
    hostRoutes: new Set([
      "account-select.tsx",
      "index.tsx",
      "layout.tsx",
      "sign-in.tsx",
      "sign-out.tsx",
    ]),
  },
  marketplace: {
    routesFileParts: ["deployables", "marketplace", "app", "context-routes.generated.ts"],
    routesDirParts: ["deployables", "marketplace", "app", "routes"],
    hostRoutes: new Set([
      "account-select.tsx",
      "chrome-devtools.ts",
      "favicon.ts",
      "index.tsx",
      "layout.tsx",
      "register.tsx",
      "robots.ts",
      "sign-in.tsx",
      "sign-out.tsx",
      "sitemap.ts",
    ]),
  },
};

export function resolveDeployableRoutePaths(repoRoot, deployable) {
  const config = deployableRouteConfig[deployable];
  if (!config) {
    throw new Error(`Unknown deployable route config: ${deployable}`);
  }

  return {
    routesFile: path.join(repoRoot, ...config.routesFileParts),
    routesDir: path.join(repoRoot, ...config.routesDirParts),
    hostRoutes: config.hostRoutes,
  };
}

export function buildWrapperContent(packageName, route) {
  const specifier = `${packageName}${route.fileExport.slice(1)}`;
  return `${generatedFileMarker}export * from "${specifier}";\nexport { default } from "${specifier}";\n`;
}

export function buildRoutesFileContent(routes) {
  if (routes.length === 0) {
    return `${generatedFileMarker}export const contextRoutes = [];\n`;
  }

  const usesIndex = routes.some((route) => route.routeType === "index");
  const importNames = usesIndex ? "index, route" : "route";
  const routeLines = routes.map((route) =>
    route.routeType === "index"
      ? `  index("routes/${route.routeId}.tsx"),`
      : `  route("${route.routePath}", "routes/${route.routeId}.tsx"),`,
  );

  return `${generatedFileMarker}import { ${importNames}, type RouteConfig } from "@react-router/dev/routes";

export const contextRoutes = [
${routeLines.join("\n")}
] satisfies RouteConfig;
`;
}
